                 'traceback': traceback.format_exc()}, 'runtime_evidence': None})
        print(json.dumps({'command': 'baseline', 'exit_code': 1, 'result_pin': file_pin(out / 'result.json')},
                         ensure_ascii=False))
        raise SystemExit(1)

